'use client'

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase/client'

export default function ReservasPublicaPage() {
  const supabase = createClient()

  const [complejo, setComplejo] = useState<any>(null)
  const [canchas, setCanchas] = useState<any[]>([])
  const [canchaSel, setCanchaSel] = useState<any>(null)
  const [fecha, setFecha] = useState('')
  const [slots, setSlots] = useState<any[]>([])
  const [slotSel, setSlotSel] = useState<string | null>(null)
  const [paso, setPaso] = useState(1)
  const [loading, setLoading] = useState(false)
  const [reservaOk, setReservaOk] = useState(false)

  const [nombre, setNombre] = useState('')
  const [telefono, setTelefono] = useState('')

  useEffect(() => {
    const cargarDatosIniciales = async () => {
      const { data: complejosData } = await supabase.from('complejos').select('*').limit(1)
      if (complejosData && complejosData.length > 0) {
        setComplejo(complejosData[0])
        const { data: canchasData } = await supabase
          .from('canchas')
          .select('*')
          .eq('complejo_id', complejosData[0].id)
          .eq('activa', true)
        setCanchas(canchasData || [])
      }
    }
    cargarDatosIniciales()
  }, [])

  const generarHorarios = async () => {
    if (!canchaSel || !fecha) return
    setLoading(true)

    // Buscamos reservas existentes
    const { data: ocupados } = await supabase
      .from('reservas')
      .select('hora_inicio')
      .eq('cancha_id', canchaSel.id)
      .eq('fecha', fecha)
      .neq('estado', 'cancelada')

    const horasOcupadas = ocupados?.map(r => r.hora_inicio.slice(0, 5)) || []
    
    // USAMOS EL HORARIO DE LA CANCHA SELECCIONADA
    const apertura = canchaSel.horario_apertura?.slice(0, 5) || "08:00"
    const cierre = canchaSel.horario_cierre?.slice(0, 5) || "23:00"

    const hApertura = parseInt(apertura.split(':')[0])
    const hCierre = parseInt(cierre.split(':')[0])

    const nuevosSlots = []
    for (let h = hApertura; h < hCierre; h++) {
      const hStr = `${h.toString().padStart(2, '0')}:00`
      nuevosSlots.push({
        hora: hStr,
        disponible: !horasOcupadas.includes(hStr)
      })
    }

    setSlots(nuevosSlots)
    setPaso(3)
    setLoading(false)
  }

  const handleReservar = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    const horaFin = `${(parseInt(slotSel!.split(':')[0]) + 1).toString().padStart(2, '0')}:00`

    const { error } = await supabase.from('reservas').insert({
      complejo_id: complejo.id,
      cancha_id: canchaSel.id,
      fecha: fecha,
      hora_inicio: slotSel,
      hora_fin: horaFin,
      cliente_nombre: nombre,
      cliente_telefono: telefono,
      monto_total: canchaSel.precio_hora,
      monto_seña: canchaSel.precio_hora / 2,
      estado: 'pendiente'
    })

    if (error) alert(error.message)
    else setReservaOk(true)
    setLoading(false)
  }

  // Interfaz (simplificada para el ejemplo, mantené tus estilos)
  if (reservaOk) return <div className="p-10 text-center"><h1>¡Reserva exitosa!</h1></div>

  return (
    <main className="max-w-md mx-auto p-4">
      <h1 className="text-2xl font-bold mb-6 text-center">{complejo?.nombre}</h1>
      
      {/* 1. CANCHAS */}
      <div className="grid gap-2 mb-6">
        {canchas.map(c => (
          <button key={c.id} onClick={() => { setCanchaSel(c); setPaso(2); }} 
            className={`p-4 border rounded-xl ${canchaSel?.id === c.id ? 'border-green-500 bg-green-50' : ''}`}>
            {c.nombre} - ${c.precio_hora}
          </button>
        ))}
      </div>

      {/* 2. FECHA */}
      {paso >= 2 && (
        <div className="flex gap-2 mb-6">
          <input type="date" className="border p-4 rounded-xl flex-1" onChange={(e) => setFecha(e.target.value)} />
          <button onClick={generarHorarios} className="bg-black text-white px-6 rounded-xl">Ver</button>
        </div>
      )}

      {/* 3. SLOTS */}
      {paso >= 3 && (
        <div className="grid grid-cols-3 gap-2 mb-6">
          {slots.map(s => (
            <button key={s.hora} disabled={!s.disponible} onClick={() => { setSlotSel(s.hora); setPaso(4); }}
              className={`p-3 rounded-lg font-bold ${!s.disponible ? 'bg-gray-100 text-gray-300' : slotSel === s.hora ? 'bg-green-600 text-white' : 'bg-white border'}`}>
              {s.hora}
            </button>
          ))}
        </div>
      )}

      {/* 4. DATOS */}
      {paso >= 4 && (
        <form onSubmit={handleReservar} className="space-y-2">
          <input type="text" placeholder="Tu nombre" required className="w-full border p-4 rounded-xl" onChange={e => setNombre(e.target.value)} />
          <input type="tel" placeholder="WhatsApp" required className="w-full border p-4 rounded-xl" onChange={e => setTelefono(e.target.value)} />
          <button className="w-full bg-green-600 text-white py-4 rounded-xl font-bold">RESERVAR</button>
        </form>
      )}
    </main>
  )
}